events = []
for cluster in clusters:
    # Candidate origin time
    median_ot = start_time + timedelta(seconds=np.median(cluster))

    # Collect all picks that match this OT
    # A P pick at station i matches if tp - OT in [0, 20]
    # An S pick at station i matches if ts - OT in [0, 35]

    matched_stations = set()
    for _, pick in picks.iterrows():
        dt = (pick['time'] - median_ot).total_seconds()
        if pick['phase'] == 'P':
            if 0 <= dt <= 20:
                matched_stations.add(pick['station'])
        elif pick['phase'] == 'S':
            if 0 <= dt <= 35:
                matched_stations.add(pick['station'])

    if len(matched_stations) >= 4:
        events.append({
            'time': median_ot,
            'num_stations': len(matched_stations)
        })

